from abc import ABC, abstractmethod
from dataclasses import dataclass
import csv
import io


@dataclass(frozen=True)
class StudentScore:
    student_id: str
    score: int

    def __post_init__(self) -> None:
        if not self.student_id.strip():
            raise ValueError("student_id cannot be blank")
        if not 0 <= self.score <= 100:
            raise ValueError("score must be from 0 to 100")


class ReportFormatter(ABC):
    @abstractmethod
    def format(self, records: list[StudentScore]) -> str:
        """Return a complete report for records."""

    def checked_records(self, records: list[StudentScore]) -> list[StudentScore]:
        if not isinstance(records, list):
            raise TypeError("records must be list")
        if not all(isinstance(item, StudentScore) for item in records):
            raise TypeError("every record must be StudentScore")
        return records


class TextFormatter(ReportFormatter):
    def format(self, records: list[StudentScore]) -> str:
        records = self.checked_records(records)
        if not records:
            return "No records"
        return "\n".join(f"{item.student_id}: {item.score}" for item in records)


class CsvFormatter(ReportFormatter):
    def format(self, records: list[StudentScore]) -> str:
        records = self.checked_records(records)
        output = io.StringIO(newline="")
        writer = csv.writer(output, lineterminator="\n")
        writer.writerow(["student_id", "score"])
        writer.writerows((item.student_id, item.score) for item in records)
        return output.getvalue()


class IncompleteFormatter(ReportFormatter):
    pass


def render(formatter: ReportFormatter, records: list[StudentScore]) -> str:
    if not isinstance(formatter, ReportFormatter):
        raise TypeError("formatter must inherit ReportFormatter")
    return formatter.format(records)


def expect(error_type: type[BaseException], action) -> None:
    try:
        action()
    except error_type:
        return
    raise AssertionError(f"expected {error_type.__name__}")


def run_checks() -> None:
    records = [StudentScore("S01", 92), StudentScore("S02", 78)]
    assert render(TextFormatter(), records) == "S01: 92\nS02: 78"
    assert render(CsvFormatter(), records) == "student_id,score\nS01,92\nS02,78\n"
    assert render(TextFormatter(), []) == "No records"
    assert render(CsvFormatter(), []) == "student_id,score\n"
    assert issubclass(TextFormatter, ReportFormatter)
    expect(TypeError, IncompleteFormatter)
    expect(TypeError, lambda: render(object(), records))
    expect(TypeError, lambda: render(TextFormatter(), ["bad"]))
    expect(ValueError, lambda: StudentScore("S03", 101))


if __name__ == "__main__":
    run_checks()
    print("abc-report checks: OK")
